//! Kaliber design tokens (plan 051), typed.
//!
//! `design/tokens/*.json` (Task 1) is the single source of truth. This
//! crate's `build.rs` reads it, strictly (`deny_unknown_fields`) — an
//! invalid token file fails the build, which is the schema gate — expands
//! each app's accent family / neutrals / dataviz series against the shared
//! formulas, and bakes the result into plain `pub static` Rust consts under
//! [`apps`]. No JSON parsing happens at runtime; there are no runtime
//! dependencies.

mod color;
pub use color::{
    accent2_chroma, contrast_ratio, fit_chroma_to_srgb, in_srgb_gamut, oklch_to_srgb, Rgba,
};

// Schema structs + parse helpers live in schema.rs. build.rs pulls the same
// file in via `include!` (it is its own compilation, outside this module
// tree); here it is a normal, test-only module so the negative-build-check
// unit test (schema.rs's `rejects_unknown_field_in_a_copy_of_base_json`)
// runs under `cargo test -p design-tokens` without the shipped library
// depending on serde at all.
#[cfg(test)]
#[allow(dead_code)] // most fields only get read by build.rs's own separate compilation
mod schema;

/// A fully-resolved theme for one app in one mode (light/dark) — every
/// field is already a concrete [`Rgba`], no OKLCH math left to do at
/// runtime. Generated by `build.rs` from `../../tokens/*.json`.
#[derive(Clone, Copy, Debug)]
pub struct Theme {
    pub background: Rgba,
    pub well: Rgba,
    pub surface_raised: Rgba,
    /// Authored in `base.json` (direction A): the secondary/ghost hover
    /// and list-row hover tone, one source for web (`--color-surface-hover`)
    /// and iced.
    pub surface_hover: Rgba,
    /// The pressed tone step (plan 125, spec R25), `--color-surface-active`.
    pub surface_active: Rgba,
    pub border: Rgba,
    /// A strong rule: the header line of a register and the dialog border.
    pub border_strong: Rgba,
    /// The 3:1 boundary of an input, select, checkbox, switch or secondary
    /// button (WCAG 1.4.11).
    pub control: Rgba,
    pub text: Rgba,
    pub text_muted: Rgba,
    /// Disabled text (plan 125, spec R25): at least 3:1 on every surface.
    pub disabled_text: Rgba,
    pub disabled_fill: Rgba,
    pub scrim: Rgba,
    /// The ink block (plan 125, spec R25): one per page, dark in both themes.
    pub ink: Rgba,
    pub on_ink: Rgba,
    pub on_ink_muted: Rgba,
    pub ink_rule: Rgba,
    /// The one action on ink and its label.
    pub ink_action: Rgba,
    pub on_ink_action: Rgba,
    pub accent: Rgba,
    pub accent_hover: Rgba,
    pub accent_active: Rgba,
    pub accent_soft: Rgba,
    pub accent_soft_active: Rgba,
    pub accent_soft_foreground: Rgba,
    /// The selected-row fill: an accent-derived tone step (`--color-surface-selected`).
    pub surface_selected: Rgba,
    pub focus: Rgba,
    pub on_accent: Rgba,
    pub danger: Rgba,
    pub danger_hover: Rgba,
    pub danger_active: Rgba,
    pub danger_soft: Rgba,
    pub warning: Rgba,
    pub warning_soft: Rgba,
    pub success: Rgba,
    pub success_soft: Rgba,
    pub chart: [Rgba; 6],
    pub chart_band_alpha: f32,
    pub chart_grid: Rgba,
}

/// One resolved identity-accent family (plan 094 Task 9, item F): an
/// `extras` entry with `formula: "accent"`, baked the same way [`Theme`]'s
/// own accent fields are -- accent, hover, active, soft and soft-foreground.
/// Generated by `build.rs` per app under
/// `apps::<app>::extras::<NAME>_LIGHT`/`_DARK`, replacing the old
/// `second_accent` field (plan 092 phase p6). The muted `rail` variant left
/// in plan 094 revision 2 (an identity rail is an AI-slop block device).
#[derive(Clone, Copy, Debug)]
pub struct AccentFamily {
    pub accent: Rgba,
    pub hover: Rgba,
    pub active: Rgba,
    pub soft: Rgba,
    pub soft_foreground: Rgba,
}

/// The tones of an optional second identity hue (plan 125, spec R35):
/// `accent2_hue` in an app's token file. Tones only, never an action, focus or
/// selected state. Generated per app as `apps::<app>::ACCENT2_LIGHT`/`_DARK`
/// (`None` for an app with one hue) and listed in [`ACCENT2`].
#[derive(Clone, Copy, Debug)]
pub struct Accent2 {
    /// A tinted section field (the soft formula at the second hue).
    pub field: Rgba,
    /// A highlight cell (the selected formula at the second hue).
    pub highlight: Rgba,
    /// A chart comparison mark or a category square (the series formula).
    pub mark: Rgba,
}

/// Theme-invariant scale tokens shared by every app: space, radius, type,
/// motion and the control height. Kaliber has no shadow token. Generated by
/// `build.rs` from `../../tokens/base.json`.
pub mod scale {
    include!(concat!(env!("OUT_DIR"), "/scale.rs"));
}

/// One module per app JSON file discovered under `../../tokens/apps/*.json`
/// at build time (kebab-case file stem -> snake_case module name, e.g.
/// `pdf-editor.json` -> `pdf_editor`). Adding a new app JSON file adds a
/// new module here automatically — no code change in this crate required.
/// Each app module also carries a nested `extras` module (Task 9): one
/// [`AccentFamily`] LIGHT/DARK pair per `formula: "accent"` entry in the
/// app's `extras` list, one flat [`Rgba`] LIGHT/DARK pair per `formula:
/// "series"` entry, named `<NAME>_LIGHT`/`<NAME>_DARK` from the extra's
/// kebab-case name. Empty (but present) for an app with no `extras`.
pub mod apps {
    include!(concat!(env!("OUT_DIR"), "/apps_mod.rs"));
}

/// Discovery registry (item B): every app `build.rs` found under
/// `tokens/apps/*.json`, as `(name, light, dark)`. Re-exported at the crate
/// root so a gate writes `design_tokens::APPS` instead of listing apps by
/// hand; adding an app JSON file adds an entry here with no code change.
pub use apps::{ACCENT2, APPS};

